const systemPrompt = `You are a sales research assistant for Cosmisk, a UGC (User Generated Content) agency in India. For each prospect brand, provide:
1. Brief research summary (2-3 bullet points about the brand)
2. A personalized outreach message (3-4 sentences, reference something specific about their brand, highlight UGC value, soft CTA for a free strategy call)
3. A follow-up message (for 3 days later, reference the first message)
4. Best outreach platform (instagram_dm, email, linkedin, or whatsapp)

Sound human, not salesy. Be specific to each brand.

Return a JSON array where each element has:
{
  "company_name": "exact company name from input",
  "research": "bullet point research",
  "message": "outreach message",
  "follow_up": "follow-up message",
  "platform": "best platform",
  "subject_line": "email subject if platform is email, else null"
}`;

const leadsList = leads.map((l, i) =>
  `${i + 1}. Company: ${l.company_name}\n   Website: ${l.website || 'unknown'}\n   Industry: ${l.industry || 'unknown'}\n   Notes: ${(l.notes || '').substring(0, 300)}`
).join('\n\n');

const userPrompt = `Research and draft outreach messages for these ${leads.length} prospects:\n\n${leadsList}\n\nReturn a JSON array with one object per prospect.`;

return [{ json: {
  systemPrompt,
  userPrompt,
  leads,
  count: leads.length,
  _skip: false
} }];

// ============================================================
// Parse Gemini batch research results
// Build: Airtable PATCH body, Slack summary, webhook response
// ============================================================
const geminiResult = $json;
const prevData = $('Prep Batch Research').first().json;
const leads = prevData.leads || [];

let results = [];
let geminiOk = false;

try {
  const text = (geminiResult.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('No Gemini response');

  let cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
  const arrMatch = cleaned.match(/\[[\s\S]*\]/);
  if (arrMatch) {
    results = JSON.parse(arrMatch[0]);
    geminiOk = true;
  }
} catch (err) {
  // Gemini failed — generate basic fallback messages
}

// Build Airtable batch PATCH and Slack message
const patchRecords = [];
const slackLines = [`:mag: *Outreach — ${leads.length} New Prospects Enriched*\n`];
const followUpDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

for (const lead of leads) {
  const match = results.find(r =>
    (r.company_name || '').toLowerCase().trim() === (lead.company_name || '').toLowerCase().trim()
  );

  let research = '';
  let message = '';
  let followUp = '';
  let platform = 'email';
  let subjectLine = '';

  if (match) {
    research = match.research || '';
    message = match.message || '';
    followUp = match.follow_up || '';
    platform = match.platform || 'email';
    subjectLine = match.subject_line || '';
  } else {
    // Fallback
    message = `Hi there, I came across ${lead.company_name} and love what you're doing. We help brands like yours create authentic UGC content that drives real results. Would you be open to a quick 15-min call to explore how we could help?`;
    followUp = `Hey, just following up on my earlier message about UGC for ${lead.company_name}. We recently helped a similar brand increase their ad performance by 40% with UGC. Happy to share the case study if you're interested!`;
    research = 'Auto-generated fallback (Gemini did not return result for this lead)';
  }

  const notesAppend = `\n\n--- AI Research ---\n${research}\n\n--- Draft Message (${platform}) ---\n${message}\n\n--- Follow-up Draft ---\n${followUp}`;
  const fullNotes = (lead.notes || '') + notesAppend;

  patchRecords.push({
    id: lead.record_id,
    fields: {
      notes: fullNotes,
      stage: 'contacted',
      next_follow_up: followUpDate
    }
  });

  slackLines.push(
    `*${lead.company_name}*` +
    (lead.industry ? ` (${lead.industry})` : '') +
    `\n  Platform: ${platform}` +
    (subjectLine ? ` | Subject: ${subjectLine}` : '') +
    `\n  Message: \"${message.substring(0, 120)}...\"` +
    `\n  Follow-up scheduled: ${followUpDate}\n`
  );
}

slackLines.push(geminiOk
  ? `_${results.length} prospects researched via Gemini. Copy messages from Airtable notes and send on respective platforms._`
  : `_Gemini failed — fallback messages generated. Review and customize before sending._`
);

return [{ json: {
  patchBody: JSON.stringify({ records: patchRecords }),
  slackMsg: slackLines.join('\n'),
  count: patchRecords.length,
  geminiOk
} }];

